## Closure-returning debounce (GCD)

```swift
import Foundation

func debounce<T>(
    delay: TimeInterval,
    queue: DispatchQueue = .main,
    action: @escaping (T) -> Void
) -> (T) -> Void {
    var workItem: DispatchWorkItem?

    return { value in
        workItem?.cancel()
        let item = DispatchWorkItem { action(value) }
        workItem = item
        queue.asyncAfter(deadline: .now() + delay, execute: item)
    }
}
```

### Usage

```swift
let search = debounce(delay: 0.3) { (query: String) in
    print("Searching for \(query)")
}

search("s")
search("sw")
search("swift") // Only this call fires, 0.3s after the last invocation
```

## Swift Concurrency version

```swift
@MainActor
final class Debouncer {
    private var task: Task<Void, Never>?
    private let delay: Duration

    init(delay: Duration) {
        self.delay = delay
    }

    func call(_ action: @escaping @MainActor () -> Void) {
        task?.cancel()
        task = Task {
            try? await Task.sleep(for: delay)
            guard !Task.isCancelled else { return }
            action()
        }
    }
}
```

### Usage

```swift
let debouncer = Debouncer(delay: .milliseconds(300))

debouncer.call { print("Fired once") }
```

## Notes

- **Debounce** waits until calls stop for `delay`, then runs only the *last* one. This differs from *throttle*, which limits how often it runs.
- The GCD version isn't thread-safe if you call it from multiple threads. Call it from one queue (such as main), or protect `workItem` with a lock.
- Keep a reference to the debounced closure or `Debouncer`. If you recreate it on every call, it won't debounce anything.

# Debouncing a Closure in Swift

Here are two approaches: a classic **GCD-based** version and a modern **Swift Concurrency** version.

## 1. GCD-based Debouncer (`DispatchWorkItem`)

```swift
import Foundation

final class Debouncer {
    private let delay: TimeInterval
    private let queue: DispatchQueue
    private var workItem: DispatchWorkItem?
    private let lock = NSLock()

    init(delay: TimeInterval, queue: DispatchQueue = .main) {
        self.delay = delay
        self.queue = queue
    }

    func call(_ action: @escaping () -> Void) {
        lock.lock()
        defer { lock.unlock() }

        // Cancel the previously scheduled work
        workItem?.cancel()

        let item = DispatchWorkItem(block: action)
        workItem = item
        queue.asyncAfter(deadline: .now() + delay, execute: item)
    }

    func cancel() {
        lock.lock()
        defer { lock.unlock() }
        workItem?.cancel()
        workItem = nil
    }
}
```

**Usage:**

```swift
let debouncer = Debouncer(delay: 0.5)

func searchTextChanged(_ text: String) {
    debouncer.call {
        print("Searching for: \(text)")
    }
}
```

## 2. Swift Concurrency Debouncer (`Task`)

```swift
actor AsyncDebouncer {
    private let duration: Duration
    private var task: Task<Void, Never>?

    init(duration: Duration) {
        self.duration = duration
    }

    func call(_ action: @escaping @Sendable () async -> Void) {
        task?.cancel()
        task = Task { [duration] in
            do {
                try await Task.sleep(for: duration)
            } catch {
                return // Cancelled before the delay elapsed
            }
            await action()
        }
    }

    func cancel() {
        task?.cancel()
        task = nil
    }
}
```

**Usage:**

```swift
let debouncer = AsyncDebouncer(duration: .milliseconds(500))

Task {
    await debouncer.call {
        await performSearch()
    }
}
```

> Requires iOS 16 / macOS 13 for `Duration` and `Task.sleep(for:)`. On older systems, use `Task.sleep(nanoseconds:)` instead.

## How It Works

- Each call **cancels** any pending execution and schedules a new one.
- The closure runs **only after** the specified delay passes with no new calls.
- Ideal for search fields, resize events, or autosave.

## Which to Choose?

| Approach | Best for |
|---|---|
| **GCD** | UIKit code, older OS targets, synchronous closures |
| **Actor/Task** | Async/await code, strict concurrency checking, SwiftUI |

Here’s a reusable debounce function using `DispatchWorkItem` to cancel pending work:

```swift
func debounce(
    delay: TimeInterval,
    queue: DispatchQueue = .main,
    action: @escaping () -> Void
) -> () -> Void {
    var workItem: DispatchWorkItem?

    return {
        workItem?.cancel()

        let newWorkItem = DispatchWorkItem(block: action)
        workItem = newWorkItem
        queue.asyncAfter(deadline: .now() + delay, execute: newWorkItem)
    }
}
```

**Usage:**

```swift
let debouncedSearch = debounce(delay: 0.3) {
    print("Searching...")
}

// Call as often as you like — e.g. on every keystroke
debouncedSearch()
debouncedSearch()
debouncedSearch() // Only this one runs, 0.3s later
```

**How it works:**
- Each call **cancels** the previously scheduled work item
- A new work item is scheduled after `delay`
- The `action` only executes if no new call arrives before the delay expires

Here's a Swift function that debounces a closure by limiting the number of times it can be called within a specified interval:

```swift
func debounce<T>(
    _ closure: @escaping () -> T,
    interval: TimeInterval,
    repeatCount: Int = 0
) -> (() -> T)? {
    var timer: Timer?
    var callCount = 0

    return {
        // Stop the timer if it's running
        timer?.invalidate()

        // Increment call count
        callCount += 1

        // Return the closure result if the limit is not reached
        guard callCount <= repeatCount else { return nil }

        // Schedule the next call after the interval, if not the last call
        if callCount < repeatCount {
            timer = Timer.scheduledTimer(withTimeInterval: interval, repeats: false) { _ in
                self.debounce(closure, interval: interval, repeatCount: self.repeatCount - 1)
            }
        }

        // Execute the closure
        return closure()
    }
}
```

**Usage Example:**

```swift
let result = debounce({
    print("Called \(Int.max) times")
}, interval: 1.0, repeatCount: 3)
```

This function ensures the closure is only executed a limited number of times, with a delay between calls.

