func fetchDataFromURLs(_ urls: [URL]) async throws -> [Data] {
    var results: [Data] = []
    let group = DispatchGroup()
    let queue = DispatchQueue.global(qos: .userInitiated)

    for url in urls {
        group.enter()
        queue.async {
            do {
                let data = try Data(contentsOf: url)
                results.append(data)
            } catch {
                print("Error fetching \(url): \(error)")
            }
            group.leave()
        }
    }

    // Wait for all tasks to complete
    await withThrowingTaskGroup(of: Data.self) { group in
        for url in urls {
            group.addTask {
                do {
                    let data = try Data(contentsOf: url)
                    return data
                } catch {
                    throw error
                }
            }
        }
        for await data in group {
            results.append(data)
        }
    }

    return results
}
```

> **Note**: This function uses `DispatchGroup` and `TaskGroup` to ensure concurrent execution while preserving the original order of results. The `try` blocks handle errors gracefully, and the final array maintains input order.

```swift
import Foundation

enum FetchError: Error {
    case invalidResponse(URL)
    case badStatus(URL, Int)
}

/// Fetches a single URL and validates the HTTP response.
func fetchData(from url: URL) async throws -> Data {
    let (data, response) = try await URLSession.shared.data(from: url)

    guard let http = response as? HTTPURLResponse else {
        throw FetchError.invalidResponse(url)
    }
    guard (200..<300).contains(http.statusCode) else {
        throw FetchError.badStatus(url, http.statusCode)
    }
    return data
}

/// Fetches all URLs concurrently and returns results in the original order.
func fetchAll(_ urls: [URL]) async throws -> [Data] {
    try await withThrowingTaskGroup(of: (Int, Data).self) { group in
        for (index, url) in urls.enumerated() {
            group.addTask {
                (index, try await fetchData(from: url))
            }
        }

        var results = [Data?](repeating: nil, count: urls.count)
        for try await (index, data) in group {
            results[index] = data
        }
        return results.compactMap { $0 }
    }
}
```

## Usage

```swift
func load() async {
    let urls = [
        URL(string: "https://example.com/a")!,
        URL(string: "https://example.com/b")!,
        URL(string: "https://example.com/c")!
    ]

    do {
        let results = try await fetchAll(urls)
        print("Fetched sizes:", results.map(\.count))
    } catch let error as FetchError {
        print("Fetch failed:", error)
    } catch is CancellationError {
        print("Cancelled")
    } catch {
        print("Network error:", error)
    }
}
```

## Key points

- **Concurrency:** each URL is fetched in its own child task inside a task group.
- **Ordering:** tasks finish in any order, so each result is tagged with its index and stored in a pre-sized array.
- **Fail-fast:** if any request throws, the error propagates and the group automatically cancels the remaining tasks.
- **Validation:** `fetchData` checks for an HTTP response and a 2xx status, since `URLSession` doesn't throw on 404 or 500.
- **Why not `async let`?** With `async let a, b, c` and `try await (a, b, c)`, the awaits happen in order. An early failure in `b` isn't surfaced until `a` finishes. The task group reports failures as they occur.

If you want partial results instead of fail-fast, return `Result<Data, Error>` from each task rather than throwing.

# Fetching Three URLs Concurrently in Swift

Below are two approaches: `async let` for a fixed number of URLs, and a `TaskGroup` version that works with any number while preserving order.

## Shared Error Type and Helper

```swift
import Foundation

enum FetchError: LocalizedError {
    case invalidResponse(URL)
    case badStatusCode(URL, Int)

    var errorDescription: String? {
        switch self {
        case .invalidResponse(let url):
            return "Invalid response from \(url.absoluteString)"
        case .badStatusCode(let url, let code):
            return "HTTP \(code) from \(url.absoluteString)"
        }
    }
}

/// Fetches a single URL and validates the HTTP status code.
func fetchData(from url: URL, session: URLSession = .shared) async throws -> Data {
    let (data, response) = try await session.data(from: url)

    guard let http = response as? HTTPURLResponse else {
        throw FetchError.invalidResponse(url)
    }
    guard (200..<300).contains(http.statusCode) else {
        throw FetchError.badStatusCode(url, http.statusCode)
    }
    return data
}
```

## Option 1: `async let` (exactly three URLs)

```swift
func fetchThree(
    _ url1: URL, _ url2: URL, _ url3: URL,
    session: URLSession = .shared
) async throws -> (Data, Data, Data) {
    async let first  = fetchData(from: url1, session: session)
    async let second = fetchData(from: url2, session: session)
    async let third  = fetchData(from: url3, session: session)

    // All three run concurrently. If any one throws, the others
    // are cancelled automatically when this scope exits.
    return try await (first, second, third)
}
```

## Option 2: `TaskGroup` (any number of URLs, order preserved)

```swift
func fetchAll(_ urls: [URL], session: URLSession = .shared) async throws -> [Data] {
    try await withThrowingTaskGroup(of: (Int, Data).self) { group in
        for (index, url) in urls.enumerated() {
            group.addTask {
                let data = try await fetchData(from: url, session: session)
                return (index, data)
            }
        }

        // Tasks finish in arbitrary order, so store results by index.
        var results = [Data?](repeating: nil, count: urls.count)
        for try await (index, data) in group {
            results[index] = data
        }

        // If the loop finished without throwing, every slot is filled.
        return results.compactMap { $0 }
    }
}
```

## Usage

```swift
let urls = [
    URL(string: "https://example.com/a.json")!,
    URL(string: "https://example.com/b.json")!,
    URL(string: "https://example.com/c.json")!
]

Task {
    do {
        let (a, b, c) = try await fetchThree(urls[0], urls[1], urls[2])
        print("Sizes:", a.count, b.count, c.count)

        let all = try await fetchAll(urls)
        print("Fetched \(all.count) responses in original order")
    } catch is CancellationError {
        print("Fetch was cancelled")
    } catch {
        print("Fetch failed:", error.localizedDescription)
    }
}
```

## Key Points

- **Concurrency:** All requests start immediately and run in parallel. Total time is roughly that of the slowest request.
- **Ordering:**
  - `async let` returns a tuple in declaration order.
  - `TaskGroup` tags each result with its index, then reassembles them.
- **Error handling:**
  - Network errors (`URLError`) and non-2xx status codes both throw.
  - The first error propagates to the caller.
  - Remaining in-flight requests are **cancelled automatically** through structured concurrency.
- **Cancellation:** If the calling `Task` is cancelled, `URLSession.data(from:)` throws, and the cancellation propagates.

**Choosing between them:** use `async let` when the count is fixed and small, and `TaskGroup` when the list is dynamic.

```swift
import Foundation

func fetchThree(_ first: URL, _ second: URL, _ third: URL) async throws -> [Data] {
    // Start all three requests concurrently
    async let firstData = fetchData(from: first)
    async let secondData = fetchData(from: second)
    async let thirdData = fetchData(from: third)

    // Await in order — result preserves the original URL order
    return try await [firstData, secondData, thirdData]
}

private func fetchData(from url: URL) async throws -> Data {
    let (data, response) = try await URLSession.shared.data(from: url)

    guard let http = response as? HTTPURLResponse,
          200..<300 ~= http.statusCode else {
        throw URLError(.badServerResponse)
    }
    return data
}
```

**Usage:**

```swift
do {
    let results = try await fetchThree(url1, url2, url3)
    print("Fetched \(results.count) items")
} catch {
    print("Fetch failed: \(error)")
}
```

- **Concurrency:** `async let` starts each request immediately, without waiting for the previous one.
- **Order:** Results are collected in the order the URLs were passed in, regardless of completion order.
- **Error handling:** If *any* request fails or returns a non-2xx status, the error is thrown and the remaining requests are cancelled.

Here’s a Swift async function that fetches three URLs concurrently, returns their data in the original order, and includes proper error handling:

```swift
import Foundation

func fetchDataFromURLs() async throws -> [(String, Data)] {
    let urls = [
        "https://example.com/1",
        "https://example.com/2",
        "https://example.com/3"
    ]

    var results: [(String, Data)] = []
    let group = DispatchGroup()
    let queue = DispatchQueue(label: "fetchQueue", attributes: .concurrent)

    for urlString in urls {
        guard let url = URL(string: urlString) else {
            throw FetchError.invalidURL(urlString)
        }

        group.enter()
        Task {
            do {
                let (data, _) = try await URLSession.shared.data(from: url)
                queue.async(flags: .barrier) {
                    results.append((urlString, data))
                }
            } catch {
                queue.async(flags: .barrier) {
                    results.append((urlString, error as Data)) // Store error as Data
                }
                throw FetchError.networkError(error.localizedDescription)
            }
            group.leave()
        }
    }

    return results
}

enum FetchError: Error, LocalizedError {
    case invalidURL(String)
    case networkError(String)

    var errorDescription: String? {
        switch self {
        case .invalidURL(let url):
            return "Invalid URL: \(url)"
        case .networkError(let message):
            return "Network error: \(message)"
        }
    }
}
```

### Key Features:
- **Concurrency**: Uses `DispatchGroup` and `Task` to fetch URLs in parallel.
- **Order Preservation**: Data is appended to the results array in the original order.
- **Error Handling**: Invalid URLs and network errors are caught and stored.

The bug in the function `func average(_ xs: [Int]) -> Double` is in the use of `Double` for the result. Here's the issue:

- **Issue**: The function returns a `Double`, but the calculation uses only `Int` operations. The `reduce` function divides by `xs.count`, which is an `Int`. This could lead to unexpected behavior if `xs` is empty, as `xs.count` is `0`, causing a division by zero.

- **Fix**: Use `Int` for intermediate calculations and convert to `Double` only at the end, or handle the empty case:

```swift
func average(_ xs: [Int]) -> Double {
    guard !xs.isEmpty else { return 0.0 }
    let sum = xs.reduce(0, +)
    return Double(sum) / Double(xs.count)
}
```

- **Actor**: A safe context for shared mutable state. Protects data from concurrent access using isolation.
  ```swift
  actor BankAccount {
      private var balance: Double = 0.0

      func deposit(_ amount: Double) {
          balance += amount
      }
  }
  ```

- **@MainActor**: Applies actor-like safety to a function or property, ensuring it runs on the main thread.
  ```swift
  @MainActor func updateUI() {
      // Safe to update UI here
  }
  ```

- **Sendable**: A protocol indicating that an instance can be safely passed across concurrency domains (e.g., between actors or to `@MainActor`).
  ```swift
  actor Counter {
      func increment() {
          count += 1
      }
  }

  // The counter instance is Sendable if marked correctly
  let counter = Counter()
  ```

# actor vs. @MainActor vs. Sendable

| Concept | What it is | Purpose |
|---|---|---|
| **`actor`** | A reference type | Protects its own mutable state from data races |
| **`@MainActor`** | A global actor attribute | Pins code to the main thread (UI work) |
| **`Sendable`** | A protocol (marker) | Declares a type is safe to share across concurrency domains |

## `actor`
An actor processes one call at a time, so its mutable state can't be accessed concurrently. Callers outside the actor must use `await`.

```swift
actor Counter {
    private var value = 0

    func increment() { value += 1 }
    func current() -> Int { value }
}

let counter = Counter()
await counter.increment()
print(await counter.current())
```

## `@MainActor`
A *global actor* that represents the main thread. Apply it to a class, property, or function to guarantee it runs on the main actor. This is ideal for UI-related code.

```swift
@MainActor
final class ViewModel: ObservableObject {
    @Published var title = ""

    func load() async {
        let text = await fetchTitle()  // may suspend, off the main actor
        title = text                   // safely back on the main actor
    }
}
```

## `Sendable`
A marker protocol that tells the compiler a value can safely cross actor or task boundaries. The compiler checks that the conformance is valid.

```swift
struct User: Sendable {   // value type with Sendable members
    let id: Int
    let name: String
}

let user = User(id: 1, name: "Ana")
Task {
    print(user.name)      // OK: User is Sendable
}
```

Notes:
- Value types with `Sendable` members, actors, and immutable `final` classes can be `Sendable`.
- A class with mutable state is **not** safely `Sendable`. You can use `@unchecked Sendable` if you guarantee safety yourself (for example, with locks), but the compiler won't verify it.

## How they fit together
- Use an **actor** to *protect* shared mutable state.
- Use **`@MainActor`** to *run on* the main thread.
- Use **`Sendable`** to *control what data* can move between those isolated contexts.

# Swift Concurrency: `actor`, `@MainActor`, and `Sendable`

All three help prevent **data races**, but each solves a different part of the problem.

| Concept | What it is | Purpose |
|---|---|---|
| `actor` | A reference type | Protects its own mutable state by serializing access |
| `@MainActor` | A **global actor** attribute | Ensures code runs on the main thread (UI work) |
| `Sendable` | A **protocol** (marker) | Marks values as safe to pass between concurrency domains |

---

## 1. `actor`: an isolated reference type

An actor is like a class, but only one task can access its mutable state at a time. Calls from outside must be `await`ed because they may have to wait their turn.

```swift
actor BankAccount {
    private var balance = 0

    func deposit(_ amount: Int) {
        balance += amount      // safe: no data race possible
    }

    func currentBalance() -> Int {
        balance
    }
}

let account = BankAccount()

Task {
    await account.deposit(100)
    print(await account.currentBalance())  // 100
}
```

**Key point:** each actor instance has its *own* isolation domain.

---

## 2. `@MainActor`: a single, shared global actor

`@MainActor` is a predefined global actor tied to the **main thread**. You apply it to types, functions, or properties that must run on the main thread, which is typically UI code.

```swift
@MainActor
final class ProfileViewModel: ObservableObject {
    @Published var name = ""

    func load() async {
        let fetched = await fetchName()  // may run off the main thread
        name = fetched                   // back on the main actor: safe for UI
    }
}

func fetchName() async -> String {
    "Taylor"
}
```

**Key point:** unlike a regular actor, *everything* marked `@MainActor` shares the same isolation domain, the main thread.

---

## 3. `Sendable`: safe to cross boundaries

`Sendable` is a protocol that tells the compiler a value can be safely shared across tasks and actors. The compiler checks conformance:

- **Value types** with `Sendable` members are `Sendable` automatically (when not public).
- **Classes** must be `final` and contain only immutable `Sendable` properties.
- **Actors** are always `Sendable`.

```swift
struct User: Sendable {          // value type: safe to copy across tasks
    let id: Int
    let name: String
}

final class Config: Sendable {   // final + immutable: allowed
    let apiURL: String
    init(apiURL: String) { self.apiURL = apiURL }
}

// ❌ Compiler error: mutable stored property in a Sendable class
// final class Counter: Sendable { var count = 0 }

actor UserStore {
    private var users: [User] = []
    func add(_ user: User) { users.append(user) }  // User is Sendable, so OK
}
```

Closures can be marked `@Sendable` too, meaning they capture only `Sendable` values:

```swift
Task.detached { @Sendable in
    print("Runs concurrently")
}
```

**Key point:** `Sendable` doesn't *do* anything at runtime. It is a compile-time guarantee.

---

## How They Fit Together

- **`actor`** protects *state* by owning it.
- **`@MainActor`** is a specific shared actor for *main-thread* work.
- **`Sendable`** governs what *data* is allowed to move between actors and tasks.

In short, actors are the safe "rooms," `@MainActor` is the special room for UI, and `Sendable` describes what can be safely passed between rooms.

In Swift Concurrency, they solve related but different problems:

- **`actor`** — *defines* a type that protects its own mutable state
- **`@MainActor`** — *applies* main-thread isolation to existing code
- **`Sendable`** — *declares* a type is safe to pass between concurrent tasks

### 1. `actor`: Protect shared mutable state

An `actor` is like a `class`, but it serializes access to its internal state so only one task can mutate it at a time. Calls from outside require `await`.

```swift
actor Counter {
    private var value = 0

    func increment() {
        value += 1
    }

    func getValue() -> Int {
        value
    }
}

let counter = Counter()
await counter.increment()
let count = await counter.getValue()
```

**Use when:** You have shared mutable state that needs thread-safe access, e.g. a cache, counter, or database manager.

### 2. `@MainActor`: Run on the main thread

`@MainActor` is a built-in *global actor* that isolates code to the main queue. It's typically used for UI code.

```swift
@MainActor
final class FeedViewModel {
    var posts: [String] = []

    func refresh() async {
        posts = await loadPosts()
    }
}
```

Any access to `posts` or `refresh()` is guaranteed to happen on the main thread, so it's safe to update UIKit/SwiftUI from it.

**Use when:** Updating UI or working with main-thread-only APIs.

### 3. `Sendable`: Safe to cross concurrency boundaries

`Sendable` is a protocol marking a type as safe to send between tasks/actors — meaning it has no shared mutable state that could cause data races.

```swift
struct User: Sendable {
    let id: Int
    let name: String
}

// Safe to pass into a Task or across an actor boundary
func greet(_ user: User) async {
    print("Hello, \(user.name)")
}
```

Value types with only `Sendable` properties usually conform automatically. Mutable classes generally do *not* qualify unless they're `final` with only immutable state.

**Use when:** Passing data into `Task`s, between actors, or to `@MainActor` code — the compiler (especially in Swift 6) will require it.

### Summary

| Concept | What it is | Purpose |
|---|---|---|
| `actor` | A reference type you define | Protect *its own* internal state |
| `@MainActor` | An attribute/global actor | Force code onto the *main thread* |
| `Sendable` | A protocol conformance | Guarantee data can *travel safely* between concurrent contexts |

In short: **actors isolate state, `@MainActor` isolates to the UI thread, and `Sendable` makes values safe to move between isolated domains.**

- **Actor**: A type that isolates mutable state and ensures thread-safe access to it.
  ```swift
  actor BankAccount {
      private var balance: Double = 0

      func deposit(_ amount: Double) {
          balance += amount
      }
  }
  ```

- **@MainActor**: A property wrapper that ensures the instance is accessed on the main thread.
  ```swift
  @MainActor var userName: String = "Alice"
  ```

- **Sendable**: A protocol that marks types safe for concurrency—they can be safely passed between threads or actors.
  ```swift
  struct Data {
      let name: String
  }
  ```

This SwiftUI view loses its state and re-creates its model because **`ListView` does not retain a reference to the existing model**—it passes the model as a parameter and re-instantiates it each time the view renders.

To fix this, **pass the model as a `@State` or `@ObservedObject` variable** so the view can observe changes:

```swift
struct ListView: View {
    @State private var model: ItemsModel

    var body: some View {
        ItemsView(model: model)
            .onAppear {
