```swift
import Foundation

class LRUCache {
    private class Node {
        let key: String
        var value: String
        var prev: Node?
        var next: Node?

        init(key: String, value: String) {
            self.key = key
            self.value = value
        }
    }

    private var cache: [String: Node] = [:]
    private var head: Node? // Most recently used
    private var tail: Node? // Least recently used

    func get(_ key: String) -> String? {
        guard let node = cache[key] else { return nil }
        // Move node to head (most recently used)
        moveToHead(node)
        return node.value
    }

    func put(_ key: String, _ value: String) {
        if let node = cache[key] {
            // Update existing node
            node.value = value
            moveToHead(node)
            return
        }

        // Create new node
        let newNode = Node(key: key, value: value)

        // Add to cache
        cache[key] = newNode

        // Insert at head
        addToHead(newNode)

        // Evict if capacity exceeds (assume capacity of 3 for demo)
        if cache.count > 3 {
            // Remove tail
            if let tailNode = tail {
                cache[tailNode.key] = nil
                removeNode(tailNode)
            }
        }
    }

    private func addToHead(_ node: Node) {
        node.next = head
        node.prev = nil
        if let headNode = head {
            headNode.prev = node
        } else {
            // First node
            tail = node
        }
        head = node
    }

    private func removeNode(_ node: Node) {
        if node.prev != nil {
            node.prev?.next = node.next
        } else {
            // Node is head
            head = node.next
        }
        if node.next != nil {
            node.next?.prev = node.prev
        } else {
            // Node is tail
            tail = node.prev
        }
    }

    private func moveToHead(_ node: Node) {
        removeNode(node)
        addToHead(node)
    }
}
```

